package com.flovex.dshop;
import org.bukkit.Bukkit;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.block.ShulkerBox;import org.bukkit.command.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.AsyncPlayerChatEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.BlockStateMeta;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.inventory.meta.PotionMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.RegisteredServiceProvider;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.potion.PotionType;import java.io.File;import java.text.DecimalFormat;import java.util.*;
public final class SellManager implements Listener,CommandExecutor,TabCompleter{
 private final JavaPlugin plugin;private final NamespacedKey marker;private final File cfgFile,worthFile,earningsFile;private YamlConfiguration cfg,worth,earnings;private Object economy;private final Map<UUID,String> searches=new HashMap<>();private final Map<UUID,Browse> browsers=new HashMap<>();
 public SellManager(JavaPlugin p){plugin=p;marker=new NamespacedKey(p,"sell_gui");cfgFile=new File(p.getDataFolder(),"sell.yml");worthFile=new File(p.getDataFolder(),"worth.yml");earningsFile=new File(p.getDataFolder(),"earnings.yml");if(!cfgFile.exists())p.saveResource("sell.yml",false);if(!worthFile.exists())p.saveResource("worth.yml",false);reloadFiles();setupEconomy();}
 public void register(){Bukkit.getPluginManager().registerEvents(this,plugin);PluginCommand c=plugin.getCommand("sell");if(c!=null){c.setExecutor(this);c.setTabCompleter(this);}}
 private void reloadFiles(){cfg=YamlConfiguration.loadConfiguration(cfgFile);worth=YamlConfiguration.loadConfiguration(worthFile);earnings=YamlConfiguration.loadConfiguration(earningsFile);}
 private void saveEarnings(){try{earnings.save(earningsFile);}catch(Exception e){plugin.getLogger().severe("Could not save seller earnings: "+e.getMessage());}}
 private void setupEconomy(){economy=null;if(Bukkit.getPluginManager().getPlugin("Vault")==null){plugin.getLogger().warning("Dshop selling requires Vault and a Vault-compatible economy plugin.");return;}try{Class<?> api=Class.forName("net.milkbowl.vault.economy.Economy",false,plugin.getClass().getClassLoader());RegisteredServiceProvider<?> r=Bukkit.getServicesManager().getRegistration(api);if(r!=null){economy=r.getProvider();plugin.getLogger().info("Dshop selling hooked into Vault economy: "+economy.getClass().getName());}else plugin.getLogger().warning("Vault is loaded, but no economy provider is registered. Install/enable an economy plugin.");}catch(Exception|LinkageError e){plugin.getLogger().severe("Could not hook Dshop selling into Vault: "+e.getClass().getSimpleName()+": "+e.getMessage());}}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("reload")){if(!p.hasPermission("dshop.admin")){p.sendMessage("§cNo permission.");return true;}reloadFiles();setupEconomy();p.sendMessage("§aDshop sell settings reloaded.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("top")){top(p);return true;}if(a.length>0&&a[0].equalsIgnoreCase("worth")){String q=a.length>1?String.join(" ",Arrays.copyOfRange(a,1,a.length)):"";worthGui(p,q,0,"VALUE");return true;}sellGui(p);return true;}
 private void sellGui(Player p){SellHolder h=new SellHolder();Inventory inv=Bukkit.createInventory(h,54,color(cfg.getString("gui.title","&8Sell Items")));h.inv=inv;ItemStack[] a=p.getInventory().getStorageContents();for(int i=0;i<Math.min(45,a.length);i++)if(a[i]!=null&&!a[i].getType().isAir())inv.setItem(i,a[i].clone());inv.setItem(49,button(Material.LIME_STAINED_GLASS_PANE,cfg.getString("gui.sell-name","&a&lSELL ITEMS"),List.of("&8&m━━━━━━━━━━━━━━━━━━","&7ꜱᴇʟʟ ɪɴᴠᴇɴᴛᴏʀʏ","&fSell all eligible items in your inventory.","","&8&m━━━━━━━━━━━━━━━━━━","&7ɪɴꜰᴏʀᴍᴀᴛɪᴏɴ","&bEstimated Total: &a$"+fmt(calculate(p)),"&bShulker Contents: &f"+(cfg.getBoolean("shulkers.enabled",true)?"Enabled":"Disabled"),"","&7ꜱᴛᴀᴛᴜꜱ: &aʀᴇᴀᴅʏ","&e▸ &fClick to Sell")));inv.setItem(45,button(Material.BOOK,"&bᴡᴏʀᴛʜ ʙʀᴏᴡꜱᴇʀ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&7ʙʀᴏᴡꜱᴇ ɪᴛᴇᴍ ᴠᴀʟᴜᴇꜱ","&fView the selling price of each item.","","&e▸ &fClick to Browse")));inv.setItem(53,button(Material.BARRIER,"&cᴄʟᴏꜱᴇ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&7Close the sell menu.","","&e▸ &fClick to Close")));p.openInventory(inv);}
 private ItemStack button(Material m,String n,List<String> lore){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.setDisplayName(color(n));x.setLore(lore.stream().map(this::color).toList());x.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);i.setItemMeta(x);return i;}
 private double materialValue(Material m){String k=m.name();if(worth.contains("prices."+k))return worth.getDouble("prices."+k);double shop=shopPrice(m);if(shop>0)return shop*cfg.getDouble("pricing.shop-price-percent",50)/100;return worth.getDouble("defaults."+k,0);}
 private double shopPrice(Material m){File dir=new File(plugin.getDataFolder(),"categories");File[] fs=dir.listFiles((d,n)->n.endsWith(".yml"));if(fs==null)return -1;for(File f:fs){YamlConfiguration y=YamlConfiguration.loadConfiguration(f);ConfigurationSection ps=y.getConfigurationSection("pages");if(ps==null)continue;for(String pg:ps.getKeys(false)){ConfigurationSection items=y.getConfigurationSection("pages."+pg+".items");if(items==null)continue;for(String id:items.getKeys(false))if(items.getString(id+".material","").equalsIgnoreCase(m.name())){double v=items.getDouble(id+".price",0);if(v>0)return v;}}}return -1;}
 private double worth(ItemStack i){if(i==null||i.getType().isAir())return 0;double v=materialValue(i.getType());if(v<=0)return 0;ItemMeta m=i.getItemMeta();if(m!=null){for(var e:m.getEnchants().entrySet())v+=worth.getDouble("enchantments."+e.getKey().getKey().getKey().toLowerCase(Locale.ROOT),0)*e.getValue();if(m instanceof PotionMeta pm&&pm.getBasePotionType()!=null)v+=worth.getDouble("potions."+pm.getBasePotionType().name().toLowerCase(Locale.ROOT),0);}return Math.max(0,v);}
 private boolean sellable(ItemStack i){return i!=null&&!i.getType().isAir()&&worth(i)>0;}
 private boolean shulker(ItemStack i){return i!=null&&i.getItemMeta() instanceof BlockStateMeta m&&m.getBlockState() instanceof ShulkerBox;}
 private double contentsWorth(ItemStack i){if(!cfg.getBoolean("shulkers.enabled",true)||!shulker(i))return 0;BlockStateMeta m=(BlockStateMeta)i.getItemMeta();ShulkerBox box=(ShulkerBox)m.getBlockState();double sum=0;for(ItemStack n:box.getInventory().getContents())if(n!=null&&!n.getType().isAir())sum+=worth(n)*n.getAmount();return sum;}
 private double calculate(Player p){double sum=0;for(ItemStack i:p.getInventory().getStorageContents())if(i!=null&&!i.getType().isAir())sum+=(shulker(i)&&!cfg.getBoolean("shulkers.sell-box",false)?0:worth(i)*i.getAmount())+contentsWorth(i);return sum;}
 private boolean deposit(Player p,double amount){if(economy==null)return false;try{for(var m:economy.getClass().getMethods()){if(!m.getName().equals("depositPlayer")||m.getParameterCount()!=2)continue;Class<?>[] t=m.getParameterTypes();if(t[0].isAssignableFrom(Player.class)&&(t[1]==double.class||t[1]==Double.class)){Object r=m.invoke(economy,p,amount);return r!=null&&Boolean.TRUE.equals(r.getClass().getMethod("transactionSuccess").invoke(r));}}}catch(Exception e){plugin.getLogger().warning("Sell payout failed: "+e.getMessage());}return false;}
 private void sell(Player p){ItemStack[] a=p.getInventory().getStorageContents();for(int k=0;k<a.length;k++)if(a[k]!=null)a[k]=a[k].clone();double sum=0;int count=0;for(int i=0;i<a.length;i++){ItemStack it=a[i];if(it==null||it.getType().isAir())continue;if(cfg.getBoolean("shulkers.enabled",true)&&shulker(it)){BlockStateMeta meta=(BlockStateMeta)it.getItemMeta();ShulkerBox state=(ShulkerBox)meta.getBlockState();Inventory box=state.getInventory();ItemStack[] inner=box.getContents();boolean changed=false;for(int j=0;j<inner.length;j++){ItemStack n=inner[j];if(!sellable(n))continue;sum+=worth(n)*n.getAmount();count+=n.getAmount();inner[j]=null;changed=true;}if(changed){box.setContents(inner);meta.setBlockState(state);it.setItemMeta(meta);}if(cfg.getBoolean("shulkers.sell-box",false)&&sellable(it)){sum+=worth(it)*it.getAmount();count+=it.getAmount();a[i]=null;}}else if(sellable(it)){sum+=worth(it)*it.getAmount();count+=it.getAmount();a[i]=null;}}
  if(count==0||sum<=0){p.sendMessage(color(cfg.getString("messages.nothing","&cYou have no sellable items.")));return;}if(!deposit(p,sum)){p.sendMessage(color(cfg.getString("messages.economy-error","&cSell failed: Vault economy is unavailable.")));return;}p.getInventory().setStorageContents(a);String id=p.getUniqueId().toString();earnings.set(id+".name",p.getName());earnings.set(id+".total",earnings.getDouble(id+".total",0)+sum);earnings.set(id+".sales",earnings.getLong(id+".sales",0)+1);earnings.set(id+".last-sale",System.currentTimeMillis());saveEarnings();p.sendMessage(color(cfg.getString("messages.sold","&aSold &f{amount} &aitems for &f{total}.").replace("{amount}",String.valueOf(count)).replace("{total}","$"+fmt(sum))));p.closeInventory();}
 private void top(Player p){p.sendMessage("§8§m-------- §bDshop Top Sellers §8§m--------");List<String> ids=new ArrayList<>(earnings.getKeys(false));ids.sort((a,b)->Double.compare(earnings.getDouble(b+".total"),earnings.getDouble(a+".total")));int n=0;for(String id:ids){if(++n>10)break;p.sendMessage("§7#"+n+" "+earnings.getString(id+".name","Unknown")+" §8» §a$"+fmt(earnings.getDouble(id+".total")));}}
 private void worthGui(Player p,String query,int page,String sort){List<Material> list=new ArrayList<>();for(Material m:Material.values()){if(!m.isItem()||m.isAir()||worth(new ItemStack(m))<=0)continue;if(!query.isBlank()&&!m.name().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;list.add(m);}if(sort.equals("NAME"))list.sort(Comparator.comparing(Material::name));else list.sort(Comparator.comparingDouble((Material m)->worth(new ItemStack(m))).reversed().thenComparing(Material::name));BrowseHolder h=new BrowseHolder();Inventory inv=Bukkit.createInventory(h,54,color("&8Dshop Item Worth"));h.inv=inv;int start=page*45;for(int n=start;n<Math.min(list.size(),start+45);n++){Material m=list.get(n);ItemStack it=new ItemStack(m);ItemMeta meta=it.getItemMeta();meta.setDisplayName(color("&f"+pretty(m.name())));meta.setLore(List.of(color("&8&m━━━━━━━━━━━━━━━━━━"),color("&7ɪɴꜰᴏʀᴍᴀᴛɪᴏɴ"),color("&bSell Price: &a$"+fmt(worth(it))),color("&7Price per item"),color(""),color("&8&m━━━━━━━━━━━━━━━━━━"),color("&7ꜱᴛᴀᴛᴜꜱ: &aꜱᴇʟʟᴀʙʟᴇ")));it.setItemMeta(meta);inv.setItem(n-start,it);}inv.setItem(45,button(Material.OAK_SIGN,"&eꜱᴇᴀʀᴄʜ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&7ꜰɪʟᴛᴇʀ ɪᴛᴇᴍꜱ","&bCurrent Search: &f"+(query.isBlank()?"All Items":query),"","&e▸ &fClick and Type in Chat")));inv.setItem(47,button(Material.ARROW,"&eᴘʀᴇᴠɪᴏᴜꜱ ᴘᴀɢᴇ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&fReturn to the previous page.","","&e▸ &fClick to Go Back")));inv.setItem(48,button(Material.HOPPER,"&bꜱᴏʀᴛ: "+(sort.equals("VALUE")?"ʜɪɢʜᴇꜱᴛ ᴠᴀʟᴜᴇ":"ɴᴀᴍᴇ"),List.of("&8&m━━━━━━━━━━━━━━━━━━","&7Change how items are arranged.","&bCurrent: &f"+(sort.equals("VALUE")?"Highest Value":"Name"),"","&e▸ &fClick to Change")));inv.setItem(49,button(Material.PAPER,"&fᴘᴀɢᴇ &b"+(page+1),List.of("&8&m━━━━━━━━━━━━━━━━━━","&7ᴘᴀɢᴇ ɪɴꜰᴏʀᴍᴀᴛɪᴏɴ","&bMatching Items: &f"+list.size())));inv.setItem(50,button(Material.ARROW,"&aɴᴇxᴛ ᴘᴀɢᴇ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&fView the next page of items.","","&e▸ &fClick to Continue")));inv.setItem(53,button(Material.BARRIER,"&cᴄʟᴏꜱᴇ",List.of("&8&m━━━━━━━━━━━━━━━━━━","&7Close the worth browser.","","&e▸ &fClick to Close")));browsers.put(p.getUniqueId(),new Browse(query,page,sort,list.size()));p.openInventory(inv);}
 private String pretty(String s){StringBuilder b=new StringBuilder();for(String w:s.toLowerCase(Locale.ROOT).split("_")){if(b.length()>0)b.append(' ');b.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1));}return b.toString();}
 @EventHandler public void chat(AsyncPlayerChatEvent e){UUID id=e.getPlayer().getUniqueId();if(!searches.containsKey(id))return;e.setCancelled(true);String q=e.getMessage().trim();Bukkit.getScheduler().runTask(plugin,()->{Player p=e.getPlayer();searches.remove(id);if(q.equalsIgnoreCase("cancel")){p.sendMessage(color("&cSearch cancelled."));return;}worthGui(p,q,0,"VALUE");});}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){Inventory top=e.getView().getTopInventory();boolean sellView=top.getHolder() instanceof SellHolder||e.getView().getTitle().equals(color(cfg.getString("gui.title","&8Sell Items")));boolean worthView=top.getHolder() instanceof BrowseHolder||e.getView().getTitle().equals(color("&8Dshop Item Worth"));if(!sellView&&!worthView)return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||e.getClickedInventory()!=top)return;int s=e.getRawSlot();if(s<0||s>=top.getSize())return;if(sellView){if(s==49)sell(p);else if(s==45)worthGui(p,"",0,"VALUE");else if(s==53)p.closeInventory();return;}Browse b=browsers.get(p.getUniqueId());if(b==null)return;if(s==45){searches.put(p.getUniqueId(),"worth");p.closeInventory();p.sendMessage(color("&eType an item name to search, or type &fcancel&e."));}else if(s==47&&b.page>0)worthGui(p,b.query,b.page-1,b.sort);else if(s==48)worthGui(p,b.query,0,b.sort.equals("VALUE")?"NAME":"VALUE");else if(s==50&&(b.page+1)*45<b.total)worthGui(p,b.query,b.page+1,b.sort);else if(s==53){browsers.remove(p.getUniqueId());p.closeInventory();}}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){Inventory top=e.getView().getTopInventory();if(top.getHolder() instanceof SellHolder||top.getHolder() instanceof BrowseHolder||e.getView().getTitle().equals(color(cfg.getString("gui.title","&8Sell Items")))||e.getView().getTitle().equals(color("&8Dshop Item Worth")))e.setCancelled(true);}
 public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){return args.length==1?List.of("top","worth","reload"):List.of();}
 private String fmt(double d){return new DecimalFormat("#,##0.##").format(d);}private String color(String s){return org.bukkit.ChatColor.translateAlternateColorCodes('&',s==null?"":s);}
 private static final class SellHolder implements InventoryHolder{Inventory inv;public Inventory getInventory(){return inv;}}
 private static final class BrowseHolder implements InventoryHolder{Inventory inv;public Inventory getInventory(){return inv;}}
 private record Browse(String query,int page,String sort,int total){}
}